INSERT INTO public.experience (id, role, organization, location, start_date, end_date, current_position, description, technologies, display_order, published)
VALUES
    (1, 'Generative AI & LLM Applications Trainee', 'Information Technology Institute (ITI) — NVIDIA DLI', 'Egypt', 'Nov 2025', 'Dec 2025', false, 'Completed intensive technical training on modern LLM architectures, prompt engineering patterns, and retrieval-augmented generation (RAG). Built end-to-end retrieval pipelines and developed Python/NLP modules for domain-specific question answering.', '["LLMs", "RAG", "Prompt Engineering", "Python", "NLP", "Ollama"]'::JSONB, 1, true),
    (2, 'Data Analysis Intern', 'National Telecommunication Institute (NTI)', 'Egypt', 'Jun 2025', 'Jul 2025', false, 'Conducted exploratory data analysis and statistical evaluation on telecom customer and operational datasets using Python and SQL. Built classification models for churn and segment prediction, generated data-driven reports, and presented visual insights.', '["Python", "SQL", "Machine Learning", "Data Analysis", "EDA", "Statistical Profiling"]'::JSONB, 2, true),
    (3, 'Data Science Member', 'Microsoft Student Club — KFS', 'Egypt', 'Oct 2025', 'Dec 2025', false, 'Collaborated on data-driven projects, machine learning challenges, and community workshops. Led peer sessions on Python data analysis, predictive modeling concepts, and Power BI report design.', '["Data Science", "Machine Learning", "Power BI", "Collaboration", "Python"]'::JSONB, 3, true),
    (4, 'Power BI Trainee', 'Microsoft Student Club — KFS', 'Egypt', 'Mar 2025', 'May 2025', false, 'Designed multi-page interactive Power BI dashboards, structured relational dimensional data models, and implemented DAX measures for executive KPI tracking and business intelligence reporting.', '["Power BI", "DAX", "Data Modeling", "Business Intelligence", "KPI Design"]'::JSONB, 4, true),
    (5, 'AI Committee Member', 'Mansoura Robotics Club', 'Mansoura, Egypt', 'Jun 2024', 'May 2025', false, 'Researched and integrated artificial intelligence and computer vision algorithms into robotics systems. Collaborated with embedded engineering teams on sensor data processing and model deployment.', '["AI", "Computer Vision", "Python", "Robotics Integration", "Teamwork"]'::JSONB, 5, true),
    (6, 'Machine Learning Member', 'IEEE Kafrelshiekh Student Branch', 'Egypt', 'Oct 2024', 'Feb 2025', false, 'Developed machine learning models for community challenges, participated in technical peer reviews, and supported university workshops introducing undergraduate students to data science tools.', '["Machine Learning", "Python", "Scikit-Learn", "Data Preprocessing"]'::JSONB, 6, true)
INSERT INTO public.projects (id, slug, title, category, category_label, accent, short_desc, value_prop, cover_image, github, live, featured, published, display_order, tech, tags)
VALUES
    (1, 'financial-market-pipeline', 'Financial Market Big Data Pipeline', 'data', 'DATA ENGINEERING', '#38bdf8', 'Production-style end-to-end pipeline for financial market analytics. Ingests daily OHLCV market data from Yahoo Finance into HDFS, executes distributed transformations with PySpark, loads a star schema in Snowflake, and feeds an analytical Power BI dashboard, all orchestrated via Dockerized Apache Airflow.', 'End-to-end market data pipeline orchestrating ingestion, distributed transformation, warehouse modeling, and business intelligence.', 'projects/financial-market-dashboard.png', 'https://github.com/mhmd-ebrahim-1/financial-market-pipeline', null, true, true, 1, '["Python", "PySpark", "HDFS", "Airflow", "Snowflake", "Power BI", "Docker"]'::JSONB, '["Python", "PySpark", "HDFS", "Airflow", "Snowflake", "Power BI", "Docker"]'::JSONB),
    (2, 'rag-ksuai', 'AI Faculty Regulations Assistant', 'ai', 'AI & NLP', '#00f5d4', 'Arabic-first RAG assistant for Kafr El-Sheikh University Faculty of AI regulations. Employs hybrid retrieval combining TF-IDF and keyword scoring with intent filtering, optional local Ollama generation, source snippet citations, caching, and retrieval-only fallback.', 'Arabic-first RAG assistant delivering instant, citation-backed academic regulation answers with local LLM inference.', 'projects/rag-ksuai-ui.png', 'https://github.com/mhmd-ebrahim-1/RAG_KSUAI', null, true, true, 2, '["Python", "RAG", "NLP", "TF-IDF", "Flask", "Ollama"]'::JSONB, '["Python", "RAG", "NLP", "TF-IDF", "Flask", "Ollama"]'::JSONB),
    (3, 'fruit-classification', 'Fruit Classification & Quality System', 'ai', 'COMPUTER VISION', '#fb923c', 'Deep learning system for real-time fruit type and quality classification. Evaluates 28 classes across 14 fruit varieties in both healthy and rotten states, featuring a web interface, Flutter mobile app, Flask API, SQLite logging, and Arduino physical sorting integration.', 'Multi-class deep learning vision system classifying fruit varieties and freshness across web, mobile, and hardware.', 'projects/fruit-classification-arch.png', 'https://github.com/mhmd-ebrahim-1/fruit-classification', null, true, true, 3, '["Python", "YOLOv8", "PyTorch", "OpenCV", "Flask", "Flutter", "Arduino"]'::JSONB, '["Python", "YOLOv8", "PyTorch", "OpenCV", "Flask", "Flutter", "Arduino"]'::JSONB),
    (4, 'healthcare-analytics', 'Healthcare Analytics Dashboard', 'data', 'DATA ANALYTICS', '#0ea5e9', 'Healthcare analytics project analyzing patient demographics, physician utilization, appointment volume, departmental revenue, and clinic expenses. Combines Python and SQL data preparation with an interactive Power BI reporting dashboard.', 'Comprehensive hospital operations and revenue intelligence platform connecting SQL processing with executive Power BI reports.', 'projects/healthcare-analytics.svg', 'https://github.com/mhmd-ebrahim-1/Healthcare-Analytics', null, true, true, 4, '["Python", "SQL", "Pandas", "Power BI", "PostgreSQL", "DAX"]'::JSONB, '["Python", "SQL", "Pandas", "Power BI", "PostgreSQL", "DAX"]'::JSONB),
    (5, 'vibecheck', 'VibeCheck — Sentiment Analyzer', 'dev', 'NLP & MOBILE', '#a78bfa', 'Android application for text and voice-based sentiment and emotion analysis with immediate visual feedback. Designed to make natural language understanding accessible through an intuitive mobile interface.', 'Accessible mobile text and speech sentiment classifier delivering instant emotion insights.', 'projects/vibecheck.svg', 'https://github.com/mhmd-ebrahim-1/VibeCheck', null, false, true, 5, '["Kotlin", "Android", "NLP", "Voice API"]'::JSONB, '["Kotlin", "Android", "NLP", "Voice API"]'::JSONB),
    (6, 'emotion-detection', 'Real-Time Facial Emotion Recognition', 'ai', 'COMPUTER VISION', '#f43f5e', 'Computer vision project for recognizing human facial emotions from live video streams using a CNN model trained with Keras/TensorFlow and an OpenCV real-time inference pipeline.', 'Deep learning facial emotion classifier running live inference through OpenCV video streams.', 'projects/emotion-detection.svg', 'https://github.com/mhmd-ebrahim-1/emotion-detection-project', null, false, true, 6, '["Python", "TensorFlow", "OpenCV", "CNN", "Keras"]'::JSONB, '["Python", "TensorFlow", "OpenCV", "CNN", "Keras"]'::JSONB),
    (7, 'movie-recommendation', 'Movie Recommendation Engine', 'ai', 'MACHINE LEARNING', '#818cf8', 'Algorithmic recommendation engine implementing regularized Non-negative Matrix Factorization (NMF) with custom Gradient Descent from scratch using Python and NumPy, without depending on high-level ML framework black boxes.', 'Recommender system implementing regularized Non-negative Matrix Factorization from scratch using pure NumPy.', 'projects/movie-recommendation.svg', 'https://github.com/mhmd-ebrahim-1/MovieRecommendation', null, false, true, 7, '["Python", "NumPy", "NMF", "Gradient Descent", "Linear Algebra"]'::JSONB, '["Python", "NumPy", "NMF", "Gradient Descent", "Linear Algebra"]'::JSONB),
    (8, 'foodmart-analytics', 'FoodMart Retail Analysis', 'data', 'BUSINESS INTELLIGENCE', '#34d399', 'Business intelligence dashboard evaluating retail store performance, analyzing historical sales trends, product category revenues, and customer purchasing patterns through interactive Power BI reports.', 'Executive retail performance dashboard analyzing sales trends, customer segments, and store margins.', 'projects/foodmart-analytics.png', 'https://github.com/mhmd-ebrahim-1/FoodMart-Retail-Analysis', null, false, true, 8, '["Power BI", "Pandas", "DAX", "Excel", "Data Modeling"]'::JSONB, '["Power BI", "Pandas", "DAX", "Excel", "Data Modeling"]'::JSONB),
    (9, 'cnc-plotter', 'Arduino CNC Plotter', 'dev', 'EMBEDDED SYSTEMS', '#f59e0b', 'Hardware-software prototyping project featuring an Arduino-controlled dual-axis stepper motor plotter. Interprets standard G-code commands for automated precision vector drawing and educational demonstrations.', 'Precision dual-axis drawing machine interpreting G-code for hardware vector plotting.', 'projects/cnc-plotter.svg', 'https://github.com/mhmd-ebrahim-1/CNC-Plotter', null, false, true, 9, '["Arduino", "C++", "G-code", "Stepper Motors", "Hardware"]'::JSONB, '["Arduino", "C++", "G-code", "Stepper Motors", "Hardware"]'::JSONB)
